// Each Hogwarts location has its own world scenery; collision layouts live in engine.cjs.
function sceneBase(top,bottom){const g=ctx.createLinearGradient(0,0,0,660);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,1200,660);}
function stoneWall(color='#9a988b14'){for(let y=0;y<570;y+=48){line(0,y,1200,y,color);for(let x=(y/48%2)*55;x<1200;x+=110)line(x,y,x,y+48,color);}}
function windowPane(x,y,w,h,color='#264051'){arch(x,y,w,h,color,'#45554b');rect(x+w/2-3,y+8,6,h-8,'#465549');rect(x,y+h*.6,w,5,'#465549');glow(x+w/2,y+h/2,100,color+'60');}
function shelf(x,y,w,h){rect(x,y,w,h,'#382e25');rect(x-5,y-5,w+10,8,'#7d6542');for(let sy=y+36;sy<y+h;sy+=50){rect(x,sy,w,7,'#947344');for(let bx=x+7;bx<x+w-12;bx+=17){const height=22+(bx%19);rect(bx,sy-height,11,height,['#835345','#6f8052','#566d81','#ac9456'][Math.floor(bx/17)%4]);rect(bx+2,sy-height+5,7,2,'#dccca655');}}}
function pot(x,y,w=40){poly([[x-w/2,y],[x+w/2,y],[x+w*.38,y+36],[x-w*.38,y+36]],'#8d6044');rect(x-w*.55,y-3,w*1.1,7,'#b8865d');}
function plant(x,y,t,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const lean=Math.sin(t+x)*7;line(0,0,lean,-65,'#8aaa62',4);for(let i=0;i<4;i++){const yy=-20-i*13,dir=i%2?1:-1;ctx.fillStyle=i%2?'#759d56':'#507c54';ctx.beginPath();ctx.ellipse(dir*13+lean*.4,yy,18,7,dir*.6,0,Math.PI*2);ctx.fill();}pot(0,0);ctx.restore();}
function tableBack(x,y,w,color='#795b3a'){rect(x,y,w,13,color);rect(x+12,y+13,13,65,'#453a2b');rect(x+w-26,y+13,13,65,'#453a2b');}
function embers(t,color='#e8cb73'){for(let i=0;i<35;i++){const x=(i*137)%1200,y=(i*79+t*9)%540;glow(x,y,3,color+'65');}}
